{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "DX-9065a, a non-peptidic small molecule with strong basic amidino groups and a carboxylic acid, had a human oral bioavailability of only 2–3%, directly supporting low F for the query's amidine/guanidine plus carboxylate ionizable motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Peramivir, a guanidine- and carboxylate-containing antiviral, had very low oral bioavailability (≤3%) in humans, supporting low F for the query's zwitterionic guanidine/carboxylate structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "A close analogue bearing an amidine and two carboxylate groups was reported to have absolute bioavailability not high enough for oral use in humans, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "The peptidomimetic ACE inhibitor metabolite S-9780/perindoprilat, containing a carboxylic acid and a peptide-like bicyclic core, showed oral bioavailability of 19% ± 7% in young healthy subjects, just below the 20% threshold and supporting low F for the query's peptidomimetic structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "L-arginine, a simple guanidine amino acid, showed high absolute oral bioavailability (68 ± 9%) at a 6 g dose in healthy men, providing some contradictory evidence that a guanidine/carboxylate zwitterion can be well absorbed, likely via amino acid transporters; this is less directly transferable to the larger, more polar peptidomimetic query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly ionized, peptidomimetic molecule with a guanidine/amidine and a carboxylic acid. High-transfer human data for closely related drug-like molecules (DX-9065a, peramivir, an amidine-diacid analogue, and perindoprilat) show very low to borderline-low oral bioavailability (2–3%, ≤3%, not high enough for oral use, 19%), supporting F <20%. The physicochemical prior of poor permeability is consistent. The high-F L-arginine data are not sufficient to override these direct low-F anchors because of the query's larger, more polar peptidomimetic structure. Prediction: low.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself.",
    "The query condition is fed state, while most cited human studies do not specify fed conditions; food effects on this highly ionized molecule are unknown.",
    "Potential carrier-mediated absorption (e.g., amino acid or peptide transporters) is not experimentally characterized for the query; L-arginine's high F suggests such a pathway could exist but is unlikely for this larger peptidomimetic.",
    "Exact dose and formulation for the query are unspecified, which can affect F for poorly permeable ionized molecules."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

